import numpy as np

# Run once/preview uses one frame.
def process(signal, params):
    threshold = float(params.get("threshold", 0.0))
    samples = np.real(np.asarray(signal))
    return (samples < threshold).astype(np.int8)

# Benchmark can vectorize a chunk with a leading frame dimension.
def process_batch(signals, params_batch):
    thresholds = np.asarray([float(params.get("threshold", 0.0)) for params in params_batch])[:, None]
    return (np.real(np.asarray(signals)) < thresholds).astype(np.int8)
